import { createRoot } from 'react-dom/client';
import App from './App.jsx';
import './index.css';
const container = document.getElementById('root');
if (!container) throw new Error('Brak #root');
createRoot(container).render(<App />);

/* src/index.css */
body {
  margin: 0;
  font-family: system-ui, sans-serif;
}
/* src/main.jsx albo main.tsx: import './index.css'; */

// src/components/Header.jsx
export function Header() { return <h1>DevDesk</h1>; }

// src/App.jsx
import { Header } from './components/Header.jsx';
export default function App() { return <Header />; }

// src/Logo.jsx
import logo from './assets/logo.svg';
export function Logo() {
  return <img src={logo} alt="DevDesk" width={32} />;
}

import logo from './assets/logo.svg';
export default function App() {
  return <img src={logo} alt="DevDesk" />;
}

type GreetingProps = { name: string };
export function Greeting({ name }: GreetingProps) {
  return <h1>Cześć, {name}!</h1>;
}
